import type { Readable, Writable } from 'node:stream';

/**
 * The only way anything in this application touches persistent bytes.
 *
 * Keys are opaque strings generated by the driver. Callers never construct
 * one, never see a filesystem path, and never learn where the bytes live —
 * which is what keeps §16's "the actual filesystem path must never be exposed"
 * true by construction rather than by remembering to redact.
 *
 * Swapping local disk for S3/MinIO means implementing this interface and
 * changing one provider binding.
 */
export interface StorageDriver {
  /** Allocate a fresh opaque key. Never derived from a client-supplied name. */
  allocateKey(): string;

  createWriteStream(key: string): Promise<Writable>;

  createReadStream(key: string): Promise<Readable>;

  delete(key: string): Promise<void>;

  stat(key: string): Promise<{ sizeBytes: number } | null>;

  /** Total bytes held, for the administrator dashboard. */
  usage(): Promise<{ bytes: number; objects: number }>;
}

export const STORAGE_DRIVER = Symbol('STORAGE_DRIVER');
